<?php
require_once __DIR__.'/includes/bootstrap.php'; require_auth(); if(role()!=='admin'){http_response_code(403);exit('Accès réservé à l’administrateur.');}
$page_title='Achats & approvisionnements';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{
 if($action==='create'){ $supplier=(int)($_POST['supplier_id']??0);$pids=$_POST['product_id']??[];$qtys=$_POST['quantite']??[];$prices=$_POST['prix_achat']??[];$lines=[];foreach($pids as $k=>$prod){$prod=(int)$prod;$qty=(float)($qtys[$k]??0);$price=(float)($prices[$k]??0);if($prod>0&&$qty>0&&$price>=0)$lines[]=[$prod,$qty,$price];}if(!$supplier||!$lines)throw new Exception('Choisissez un fournisseur et au moins un article avec une quantité valide.');$reference='BA-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO bons_achat(reference,fournisseur_id,date_bon,statut) VALUES(?,?,CURRENT_DATE,'envoye')");$s->execute([$reference,$supplier]);$id=(int)db_last_insert_id($pdo,'bons_achat');$s=$pdo->prepare('INSERT INTO bons_achat_lignes(bon_id,produit_id,quantite_commandee,prix_unitaire) VALUES(?,?,?,?)');foreach($lines as $line)$s->execute([$id,$line[0],$line[1],$line[2]]);$pdo->commit();flash('Bon d’achat créé avec '.count($lines).' ligne(s). À la réception, utilisez le bouton Réceptionner.'); }
 elseif($action==='receive'){ $id=(int)$_POST['id'];$s=$pdo->prepare("SELECT * FROM bons_achat WHERE id=?");$s->execute([$id]);$po=$s->fetch();if(!$po||in_array($po['statut'],['recu','annule'],true))throw new Exception('Ce bon ne peut pas être réceptionné.');$s=$pdo->prepare('SELECT * FROM bons_achat_lignes WHERE bon_id=?');$s->execute([$id]);$lines=$s->fetchAll();if(!$lines)throw new Exception('Le bon ne contient aucun article.');$call=$pdo->prepare('CALL sp_receptionner_ligne(?,?,?)');foreach($lines as $line){$reste=(float)$line['quantite_commandee']-(float)$line['quantite_recue'];if($reste>0){$call->execute([(int)$line['id'],$reste,(int)$_SESSION['user']['id']]);$call->closeCursor();}}flash('Réception enregistrée : le stock a été augmenté.'); }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}redirect('purchases.php');}
$suppliers=$pdo->query('SELECT id,nom FROM fournisseurs ORDER BY nom')->fetchAll();$products=$pdo->query('SELECT id,libelle,unite FROM produits_stock WHERE actif=1 ORDER BY libelle')->fetchAll();$rows=$pdo->query('SELECT p.*, f.nom AS fournisseur, (SELECT SUM(i.quantite_commandee*i.prix_unitaire) FROM bons_achat_lignes i WHERE i.bon_id = p.id) AS total, (SELECT COUNT(*) FROM bons_achat_lignes i WHERE i.bon_id = p.id) AS lignes FROM bons_achat p JOIN fournisseurs f ON f.id = p.fournisseur_id ORDER BY p.id DESC')->fetchAll();require 'includes/header.php';?>
<div class="panel"><h2>Créer un bon d'achat</h2><?php if(!$suppliers||!$products):?><p class="notice">Ajoutez d'abord au moins un fournisseur et un produit dans les modules Fournisseurs et Stock.</p><?php else:?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><div class="field"><label>Fournisseur</label><select name="supplier_id" required><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['nom'])?></option><?php endforeach;?></select></div><div class="field full"><label>Articles du bon (jusqu'à 4 lignes)</label><?php for($i=0;$i<4;$i++):?><div class="form-grid" style="margin:8px 0"><div class="field"><label>Produit</label><select name="product_id[]"><option value="0">— Aucun —</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['libelle'].' ('.$x['unite'].')')?></option><?php endforeach;?></select></div><div class="field"><label>Quantité</label><input type="number" step="0.01" min="0" name="quantite[]" value="0"></div><div class="field"><label>Prix d'achat unitaire (FCFA)</label><input type="number" step="1" min="0" name="prix_achat[]" value="0"></div></div><?php endfor;?></div><div class="field full"><button class="btn">＋ Créer le bon d'achat</button></div></form><?php endif;?></div>
<div class="panel"><h2>Historique des achats</h2><div class="table-wrap"><table><thead><tr><th>N° bon</th><th>Date</th><th>Fournisseur</th><th>Lignes</th><th>Total estimé</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['date_bon'])?></td><td><?=e($r['fournisseur'])?></td><td><?=$r['lignes']?></td><td><?=money($r['total']??0)?></td><td><span class="badge"><?=e($r['statut'])?></span></td><td><?php if(!in_array($r['statut'],['recu','annule'],true)):?><form method="post" onsubmit="return confirm('Confirmer la réception et augmenter le stock ?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="receive"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn green small">Réceptionner</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">Aucun achat enregistré.</td></tr><?php endif;?></tbody></table></div><p class="notice">La réception d'un bon crée automatiquement les entrées de stock. Chaque bon est réceptionné une seule fois pour éviter les doublons.</p></div><?php require 'includes/footer.php';?>